542	func TestExpiry(t *testing.T) {
543		w, c := setupApproval(t)
544		// 用一条 1 小时后才到期的会话，避免重申请时先被会话过期拦截。
545		if _, err := w.CreateSession("s-long", "u1", "dev1", c.t.Add(time.Hour)); err != nil {
546			t.Fatal(err)
547		}
548		in := approvalApply()
549		in.SessionID = "s-long"
550		if _, err := w.Apply(in); err != nil {
551			t.Fatal(err)
552		}
553	
554		// 到期前查询仍为待审批。
555		if req, _ := w.Request("u1", "r1"); req.State != RequestPendingApproval {
556			t.Fatalf("state before expiry = %v", req.State)
557		}
558	
559		// 推进到等待期限（1 分钟）：到期时刻即过期。
560		c.t = c.t.Add(time.Minute)
561		req, err := w.Request("u1", "r1")
562		if err != nil {
563			t.Fatal(err)
564		}
565		if req.State != RequestExpired {
566			t.Fatalf("state = %v, want expired", req.State)
567		}
568		if req.DecidedAt.IsZero() {
569			t.Fatal("expired request should have decision time")
570		}
571	
572		// 账本含过期留痕。
573		var found bool
574		for _, e := range w.Ledger() {
575			if e.Kind == LedgerExpiration && e.RequestID == "r1" {
576				found = true
577				if e.AccountID != "u1" || e.Amount != 0 {
578					t.Fatalf("expiration entry = %+v", e)
579				}
580			}
581		}
582		if !found {
583			t.Fatal("missing LedgerExpiration entry")
584		}
585	
586		// 截止时刻及之后不能批准。
587		if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); !errors.Is(err, ErrApprovalExpired) {
588			t.Fatalf("approve after deadline err = %v, want ErrApprovalExpired", err)
589		}
590		// 过期不能拒绝、不能取消、不能结算。
591		if _, err := w.Reject("u1", "r1", "sa", "dev-approve", "late"); !errors.Is(err, ErrRequestNotPending) {
592			t.Fatalf("reject expired err = %v, want ErrRequestNotPending", err)
593		}
594		if _, err := w.Cancel("u1", "r1"); !errors.Is(err, ErrRequestNotReserved) {
595			t.Fatalf("cancel expired err = %v, want ErrRequestNotReserved", err)
596		}
597		if _, err := w.Settle("u1", "r1", 0); !errors.Is(err, ErrRequestNotReserved) {
598			t.Fatalf("settle expired err = %v, want ErrRequestNotReserved", err)
599		}
600	
601		// 过期请求不能通过重复申请重新创建（会话仍有效，应返回过期视图）。
602		if req, err := w.Apply(in); err != nil || req.State != RequestExpired {
603			t.Fatalf("re-apply expired: view=%+v err=%v", req, err)
604		}
605	}
