	}
	if len(w.Ledger()) != before {
		t.Fatal("ledger grew on idempotent pending apply")
	}
	// 内容不同：冲突。
	conflict := in
	conflict.EstimatedFee = 21
	if _, err := w.Apply(conflict); !errors.Is(err, ErrConflict) {
		t.Fatalf("err = %v, want ErrConflict", err)
